(187498, 10499, 5964, '<td valign="top">I guess not a subject I would have considered to photograph, but nicely executed except for the shadow.</td>', 'I guess not a subject I would have considered to photograph, but nicely executed except for the shadow.', '2003-01-12 10:33:59.000000', NULL, 1),
(187509, 10366, 4517, '<td valign="top">very good. 10</td>', 'very good. 10', '2003-01-12 12:10:12.000000', NULL, 1),
